/**
 * Generate `tables.inc` for the native RFD4-Proteina featuriser.
 *
 * 🔴 DERIVED, NEVER TYPED. Every table here already exists in `shared/rfd4p/`, and this port's own
 * recurring lesson is that a constant copied by hand is a second place for a convention to live.
 * `test/rfd4p-native-tables.test.js` fails when the generated file is stale, as
 * `test/native-featuriser-tables.test.js` does for the AF3 side.
 *
 *     node cuda/rfd4p/featurise/gen-tables.mjs > cuda/rfd4p/featurise/tables.inc
 */
import {
  UNIFIED_ATOM37_TOKENS, UNIFIED_ATOM37_ENCODING, UNIFIED_RESTYPE_ATOM37_MASK,
  ALLOWED_RESIDUE_TYPES, STANDARD_POLYMER_RESIDUES, LOCAL_LATENT_RESIDUE_SET,
  TokenType, TOKEN_TYPE_IDS, RESIDUES_BY_TOKEN_TYPE, ATOM37_NAMES,
} from "../../../shared/rfd4p/encoding.js";
import { CHAIN_TYPE, BOND_TYPE } from "../../../shared/rfd4p/pipeline/cif.js";
import { CONDITION_ENUMS, CONDITION_REGISTRY } from "../../../shared/rfd4p/pipeline/spec.js";
import { parseCathCode } from "../../../shared/rfd4p/conditions.js";

const str = (s) => JSON.stringify(s);
const out = [];
const w = (s) => out.push(s);

w("// GENERATED by cuda/rfd4p/featurise/gen-tables.mjs - do not edit.");
w("// The RFD4-Proteina vocabulary and conventions, derived from shared/rfd4p/ rather than typed.");
w("#pragma once");
w("#include <array>");
w("#include <cstdint>");
w("#include <string>");
w("#include <unordered_map>");
w("#include <vector>");
w("");
w("namespace rfd4p {");
w("namespace tables {");
w("");

const nTok = UNIFIED_ATOM37_TOKENS.length;
w(`constexpr int N_TOKENS = ${nTok};`);
w("constexpr int N_ATOM37 = 37;");
w(`constexpr int N_TOKEN_TYPES = ${Object.keys(TokenType).length};`);
w("");

w("// Every residue token, in vocabulary order; the index IS `residue_type`.");
w(`inline const std::array<const char*, ${nTok}> TOKENS = {`);
for (let i = 0; i < nTok; i += 8) {
  w("    " + UNIFIED_ATOM37_TOKENS.slice(i, i + 8).map(str).join(", ") + ",");
}
w("};");
w("");

w("// `[token][slot]` atom names, empty where the token has no atom in that slot.");
w(`inline const std::array<std::array<const char*, 37>, ${nTok}> TOKEN_ATOMS = {{`);
for (const t of UNIFIED_ATOM37_TOKENS) {
  const atoms = UNIFIED_ATOM37_ENCODING.token_atoms[t];
  w("    {{" + Array.from({ length: 37 }, (_, s) => str(atoms[s] ?? "")).join(", ") + "}},");
}
w("}};");
w("");

w("// `restype_atom37_mask`: which of the 37 slots a token occupies.");
w(`inline const std::array<uint8_t, ${nTok * 37}> RESTYPE_ATOM37_MASK = {`);
const mask = UNIFIED_RESTYPE_ATOM37_MASK.flatMap((r) => Array.from(r));
for (let i = 0; i < mask.length; i += 37) w("    " + mask.slice(i, i + 37).join(",") + ",");
w("};");
w("");

w("// `get_allowed_residue_type_mask`: which residues a token TYPE admits.");
w(`inline const std::array<uint8_t, ${ALLOWED_RESIDUE_TYPES.length * nTok}> ALLOWED_RESIDUE_TYPES = {`);
for (const row of ALLOWED_RESIDUE_TYPES) w("    " + Array.from(row).join(",") + ",");
w("};");
w("");

w("// The 28 standard polymer residues, in the order the sequence-probability keys take.");
w(`inline const std::array<const char*, ${STANDARD_POLYMER_RESIDUES.length}> STANDARD_POLYMER_RESIDUES = {`);
w("    " + STANDARD_POLYMER_RESIDUES.map(str).join(", ") + ",");
w("};");
w("");

w("// The residues that carry a local latent (`supports_local_latent`).");
const latent = [...LOCAL_LATENT_RESIDUE_SET].sort();
w(`inline const std::array<const char*, ${latent.length}> LOCAL_LATENT_RESIDUES = {`);
for (let i = 0; i < latent.length; i += 8) w("    " + latent.slice(i, i + 8).map(str).join(", ") + ",");
w("};");
w("");

w("// The atom37 slot names, and which residues each token type admits.");
w(`inline const std::array<const char*, 37> ATOM37_NAMES = {`);
w("    " + ATOM37_NAMES.map(str).join(", ") + ",");
w("};");
w("");

w("enum TokenTypeId : int {");
for (const [k, v] of Object.entries(TokenType)) w(`  TT_${k} = ${v},`);
w("};");
w("");
w("inline const std::unordered_map<std::string, int> TOKEN_TYPE_IDS = {");
for (const [k, v] of Object.entries(TOKEN_TYPE_IDS)) w(`    {${str(k)}, ${v}},`);
w("};");
w("");
w("inline const std::unordered_map<std::string, std::vector<std::string>> RESIDUES_BY_TOKEN_TYPE = {");
for (const [k, names] of Object.entries(RESIDUES_BY_TOKEN_TYPE)) {
  w(`    {${str(k)}, {${names.map(str).join(", ")}}},`);
}
w("};");
w("");

w("enum ChainType : int {");
for (const [k, v] of Object.entries(CHAIN_TYPE)) if (typeof v === "number") w(`  CT_${k} = ${v},`);
w("};");
w("enum BondType : int {");
for (const [k, v] of Object.entries(BOND_TYPE)) if (typeof v === "number") w(`  BT_${k} = ${v},`);
w("};");
w("");
w("// The condition enums, by spec name then by member - what `C_SEC: {HELIX: ...}` resolves to.");
w("inline const std::unordered_map<std::string, std::unordered_map<std::string, int>> CONDITION_ENUMS = {");
for (const [name, members] of Object.entries(CONDITION_ENUMS)) {
  w(`    {${str(name)}, {${Object.entries(members).map(([k, v]) => `{${str(k)}, ${v}}`).join(", ")}}},`);
}
w("};");
w("");
w("// The 1-body condition registry: a spec key to its batch key, its dtype and its enum.");
w("struct ConditionSpec { const char* fullName; const char* dtype; const char* enumName; };");
w("inline const std::unordered_map<std::string, ConditionSpec> CONDITION_REGISTRY = {");
const enumName = (e) => Object.entries(CONDITION_ENUMS).find(([, v]) => v === e)?.[0] ?? "";
for (const [key, spec] of Object.entries(CONDITION_REGISTRY)) {
  w(`    {${str(key)}, {${str(spec.fullName)}, ${str(spec.dtype)}, ${str(enumName(spec.enum))}}},`);
}
w("};");
w("");
w("// 🔴 THE CATH CODE IS THREE INDICES, NOT A STRING, and the maps are not a numbering anybody");
w("// could re-derive - `3.40.50` is [2, 23, 890]. Generated by calling the reference's own parser");
w("// over every code the three maps between them can spell.");
w("inline const std::unordered_map<std::string, std::array<int, 3>> CATH_CODES = {");
{
  const { CATH_CLASS_MAP, CATH_ARCHITECTURE_MAP, CATH_TOPOLOGY_MAP } =
    await import("../../../shared/rfd4p/conditions.js");
  const codes = new Set();
  for (const c of Object.keys(CATH_CLASS_MAP)) codes.add(c);
  for (const a of Object.keys(CATH_ARCHITECTURE_MAP)) codes.add(a);
  for (const t of Object.keys(CATH_TOPOLOGY_MAP)) codes.add(t);
  for (const code of [...codes].sort()) {
    const v = parseCathCode(code);
    if (v) w(`    {${str(code)}, {${v.join(", ")}}},`);
  }
}
w("};");
w("");
w("}  // namespace tables");
w("}  // namespace rfd4p");

const text = out.join("\n") + "\n";
// `--check` is what the test runs: it compares rather than writes, so a stale file is a red gate
// and not a diff somebody has to notice.
if (process.argv.includes("--check")) {
  const { readFileSync } = await import("node:fs");
  const path = new URL("./tables.inc", import.meta.url).pathname;
  let have = "";
  try { have = readFileSync(path, "utf8"); } catch { /* absent counts as stale */ }
  if (have === text) {
    console.log("cuda/rfd4p/featurise/tables.inc is current");
    process.exit(0);
  }
  console.error("cuda/rfd4p/featurise/tables.inc is STALE - regenerate it:");
  console.error("  node cuda/rfd4p/featurise/gen-tables.mjs > cuda/rfd4p/featurise/tables.inc");
  process.exit(1);
}
process.stdout.write(text);
